import { useEffect, useMemo, useState } from "react";
import { api, type Site } from "../api/client";

/**
 * Planner tab: SitePlanner (the proven single-file planning tool) embedded
 * same-origin in an iframe. The ?embedded=1&site=<id> query switches the
 * planner into cloud mode (save/load to the dashboard, live 5-state feed).
 */
export function PlannerView() {
  const [sites, setSites] = useState<Site[]>([]);
  const [siteId, setSiteId] = useState<string>("");
  const [note, setNote] = useState<string>("");

  // Setup checklist: generated by SitePlanner from the plan (devices + cable
  // runs) and stored with the cloud plan on ☁ Save.
  async function downloadChecklist() {
    if (!siteId) return;
    setNote("");
    try {
      const r = await fetch(`/map/plans/${siteId}/checklist`, { credentials: "same-origin" });
      if (r.status === 404) {
        setNote("No checklist yet. Draw the plan, then ☁ Save in the planner.");
        return;
      }
      if (!r.ok) {
        setNote(`Couldn't get the checklist (HTTP ${r.status}).`);
        return;
      }
      const blob = new Blob([JSON.stringify(await r.json(), null, 2)], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = "setup_checklist.json";
      a.click();
      setTimeout(() => URL.revokeObjectURL(url), 1500);
    } catch (e) {
      setNote(`Couldn't get the checklist: ${e instanceof Error ? e.message : String(e)}`);
    }
  }

  useEffect(() => {
    api
      .sites()
      .then((ss) => {
        setSites(ss);
        if (ss.length && !siteId) {
          const main = ss.find((s) => s.name.toLowerCase() === "main");
          setSiteId((main ?? ss[0]).id);
        }
      })
      .catch(() => {});
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const src = useMemo(
    () => `/planner/index.html?embedded=1${siteId ? `&site=${siteId}` : ""}`,
    [siteId],
  );

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "calc(100vh - 120px)" }}>
      <div className="devices-toolbar" style={{ marginBottom: 10 }}>
        <div className="panel-title" style={{ margin: 0 }}>Site plan</div>
        {sites.length > 1 ? (
          <select
            className="search"
            style={{ marginLeft: 12, padding: "4px 8px" }}
            value={siteId}
            onChange={(e) => setSiteId(e.target.value)}
          >
            {sites.map((s) => (
              <option key={s.id} value={s.id}>{s.name}</option>
            ))}
          </select>
        ) : null}
        <div className="spacer" />
        {note ? <span style={{ fontSize: 12, color: "var(--muted)", marginRight: 10 }}>{note}</span> : null}
        <button
          className="btn"
          style={{ marginRight: 8 }}
          onClick={downloadChecklist}
          disabled={!siteId}
          title="The setup checklist from the saved plan: every planned device and cable run"
        >
          ⬇ Setup checklist
        </button>
        <a className="btn" href={src} target="_blank" rel="noreferrer" title="Open the planner full-screen in its own tab">
          ⧉ Open full-screen
        </a>
      </div>
      <iframe
        key={src}
        src={src}
        title="SitePlanner"
        style={{
          flex: 1,
          width: "100%",
          border: "1px solid var(--border)",
          borderRadius: "var(--radius)",
          background: "#fff",
        }}
      />
    </div>
  );
}
